"use client"

import type { ColumnDef } from "@/lib/feature-kit/data-table"
import {
	DataTable,
	DataTableColumnHeader,
	RowActionDelete,
	RowActionEdit,
	type RowActionComponentProps,
	commonColumns,
} from "@/lib/feature-kit/data-table"
import { FormKit } from "@/lib/feature-kit/form"
import { ContentPageHeader, DashboardShell, FormSection } from "@/lib/feature-kit/layout"
import { Plus } from "lucide-react"
import { useCallback, useMemo, useState } from "react"
import { toast } from "sonner"
import { z } from "zod"

import { BlockPageRoot } from "@/components/blocks/block-page-root"
import { LayoutShellSidebarSlots } from "@/components/examples/layout/shell/layout-shell-shared"
import { demoPeople, statusFilterOptions, type DemoPerson } from "@/components/examples/table/demo-rows"
import { Button } from "@/components/ui/button"
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from "@/components/ui/sheet"

const slots = LayoutShellSidebarSlots()

const personSchema = z.object({
	name: z.string().min(1, "Name is required"),
	email: z.string().email("Enter a valid email"),
	status: z.enum(["active", "invited", "disabled"]),
})

const roleOptions = statusFilterOptions.map((o) => ({ value: o.value, label: o.label }))

function CrudDeleteAction(props: RowActionComponentProps<DemoPerson>) {
	return (
		<RowActionDelete<DemoPerson>
			{...props}
			onDelete={async (person) => {
				await new Promise((r) => setTimeout(r, 250))
				toast.success("Removed", { description: person.name })
			}}
		/>
	)
}

export function DataTableCrudBlock() {
	const [sheetOpen, setSheetOpen] = useState(false)
	const [editing, setEditing] = useState<DemoPerson | null>(null)

	const openCreate = () => {
		setEditing(null)
		setSheetOpen(true)
	}

	const openEdit = useCallback((row: DemoPerson) => {
		setEditing(row)
		setSheetOpen(true)
	}, [])

	const columns = useMemo<ColumnDef<DemoPerson>[]>(
		() => {
			function CrudEditAction(props: RowActionComponentProps<DemoPerson>) {
				return <RowActionEdit<DemoPerson> {...props} label="Edit" onEdit={openEdit} />
			}

			return [
			...commonColumns.selectColumn<DemoPerson>(),
			{
				id: "name",
				accessorKey: "name",
				meta: { labelKey: "Name", filter: { search: true, sort: true } },
				header: ({ column }) => <DataTableColumnHeader column={column} title="Name" />,
			},
			{
				id: "email",
				accessorKey: "email",
				meta: { labelKey: "Email", filter: { search: true } },
				header: ({ column }) => <DataTableColumnHeader column={column} title="Email" />,
			},
			{
				id: "status",
				accessorKey: "status",
				meta: {
					labelKey: "Status",
					filter: { options: true, staticOptions: statusFilterOptions },
				},
				header: ({ column }) => <DataTableColumnHeader column={column} title="Status" />,
			},
			...commonColumns.actionsColumn<DemoPerson>({
				actions: [CrudEditAction, CrudDeleteAction],
			}),
		]
		},
		[openEdit],
	)

	return (
		<BlockPageRoot>
			<DashboardShell {...slots}>
				<ContentPageHeader
					actions={
						<Button size="sm" onClick={openCreate}>
							<Plus className="size-4" aria-hidden />
							New account
						</Button>
					}
					description="Filters, row actions, and a sheet form for create/edit."
					title="Accounts"
				/>
				<div className="mt-4 min-h-0 flex-1 overflow-hidden rounded-lg border bg-card">
					<DataTable
						columns={columns}
						data={demoPeople}
						displayKey="name"
						pinnedFilterKeys={["status"]}
						selectionKey={(row) => row.id}
						syncUrl={false}
						tableId="block-crud-table"
					/>
				</div>
				<Sheet
					onOpenChange={(open) => {
						setSheetOpen(open)
						if (!open) setEditing(null)
					}}
					open={sheetOpen}>
					<SheetContent className="overflow-y-auto sm:max-w-md">
						<SheetHeader>
							<SheetTitle>{editing ? "Edit account" : "New account"}</SheetTitle>
							<SheetDescription>
								{editing ? "Update account fields and save." : "Add a row to the demo table (no API)."}
							</SheetDescription>
						</SheetHeader>
						<div className="mt-6">
							<FormKit
								defaultValues={
									editing
										? {
												name: editing.name,
												email: editing.email,
												status: editing.status,
											}
										: { name: "", email: "", status: "active" as const }
								}
								resetOnSuccess
								schema={personSchema}
								onSubmit={async (values) => {
									await new Promise((r) => setTimeout(r, 400))
									toast.success(editing ? "Account updated" : "Account created", {
										description: values.name,
									})
									setSheetOpen(false)
									setEditing(null)
								}}>
								<FormSection title="Account">
									<FormKit.Field label="Name" name="name" required type="text" />
									<FormKit.Field label="Email" name="email" required type="text" />
									<FormKit.Field label="Status" name="status" options={roleOptions} type="select" />
								</FormSection>
								<FormKit.Actions>
									<FormKit.Reset label="Reset" />
									<FormKit.Submit label="Save" pendingLabel="Saving…" />
								</FormKit.Actions>
							</FormKit>
						</div>
					</SheetContent>
				</Sheet>
			</DashboardShell>
		</BlockPageRoot>
	)
}

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"

/** Full-viewport root for block iframe previews. */
export function BlockPageRoot({ children, className }: { children: ReactNode; className?: string }) {
	return (
		<div className={cn("flex h-dvh min-h-0 flex-col overflow-hidden bg-background text-foreground", className)}>
			{children}
		</div>
	)
}

"use client"

import {
	DashboardAccountMenu,
	DashboardSidebarBrand,
	DashboardSidebarNav,
} from "@/lib/feature-kit/layout"
import { LayoutGrid } from "lucide-react"
import type { ReactNode } from "react"

import { SignOutDropdownMenuItem } from "@/lib/feature-kit/auth"
import { ThemeSelector } from "@/lib/feature-kit/theme"

import { workspaceNavGroups } from "./layout-demo-nav"

export function LayoutShellBrand() {
	return (
		<DashboardSidebarBrand
			href="/docs"
			logo={
				<div className="flex aspect-square size-8 items-center justify-center rounded-lg bg-primary text-primary-foreground">
					<LayoutGrid className="size-4" />
				</div>
			}
			subtitle="Playground"
			title="Feature Kit"
		/>
	)
}

export function LayoutShellSidebarNav() {
	return <DashboardSidebarNav groups={workspaceNavGroups} />
}

export function LayoutShellAccountMenu({
	user = { name: "Demo User", email: "demo@featurekit.dev" },
}: {
	user?: { name: string; email: string; image?: string | null }
}) {
	return (
		<DashboardAccountMenu signOutItem={<SignOutDropdownMenuItem />} user={user} />
	)
}

export function LayoutShellHeaderActions() {
	return <ThemeSelector label="Theme" />
}

export function LayoutShellSidebarFooter({ user }: { user?: { name: string; email: string } }) {
	return <LayoutShellAccountMenu {...(user ? { user } : {})} />
}

export function LayoutShellSidebarSlots(): {
	sidebarHeader: ReactNode
	sidebarContent: ReactNode
	sidebarFooter: ReactNode
	headerActions: ReactNode
} {
	return {
		sidebarHeader: <LayoutShellBrand />,
		sidebarContent: <LayoutShellSidebarNav />,
		sidebarFooter: <LayoutShellSidebarFooter />,
		headerActions: <LayoutShellHeaderActions />,
	}
}
